"""Editorial content for Antillia case studies. PL first; English translation second."""
CASES=[
dict(slug='demandcast',folder='01-demandcast',name='DemandCast',category=('Prognozowanie popytu','Demand forecasting'),headline=('Historia ruchu.','A history of movement.'),accent=('Plan na jutro.','A plan for tomorrow.'),intro=('Zbudowaliśmy laboratorium prognoz, które zamienia siedem dni historii w porównywalne scenariusze na kolejne 24 godziny. Z modelem bazowym, siecią GRU i wynikami, które można odtworzyć.','We built a forecasting laboratory that turns seven days of history into comparable scenarios for the next 24 hours. With a baseline, a GRU network and results that can be reproduced.'),problem=('Ile zasobów przygotować na następną dobę?','How many resources will tomorrow need?'),problem_body=('Sama średnia nie pokazuje porannego szczytu ani spokojnej nocy. Potrzebny jest profil godzinowy, który da się porównać z rzeczywistością i ocenić bez podglądania przyszłości.','An average does not show the morning peak or the quiet hours at night. A useful forecast needs an hourly profile that can be compared with observations without looking into the future.'),features=[('Prognoza na 24 godziny','24-hour forecast','168 godzin historii, znany kalendarz i trzy porównywane metody.','168 historical hours, known calendar features and three comparable methods.'),('Scenariusze popytu','Demand scenarios','Zmiana skali historii pozwala zobaczyć reakcję modeli; scenariusz jest oznaczony osobno od benchmarku.','Scaling history reveals model behavior; scenarios are clearly separated from the benchmark.'),('Powtarzalny eksperyment','Reproducible experiment','Zapisane wagi, granice czasowe, predykcje CSV i osobna walidacja.','Saved weights, temporal boundaries, CSV predictions and separate validation.')],uses=[('Planowanie zasobów','Resource planning','Punkt wyjścia do planowania floty, dyżurów lub obsady na danych konkretnej firmy.','A starting point for fleet, shift or staffing plans using a company’s own data.'),('Analiza sezonowości','Seasonality analysis','Porównanie rytmu dobowego i tygodniowego przed wyborem bardziej złożonego modelu.','Compare daily and weekly patterns before selecting a more complex model.'),('Ocena koncepcji','Feasibility assessment','Sprawdzenie, czy dodatkowa złożoność rzeczywiście poprawia wynik.','Check whether additional complexity actually improves the result.')],steps=[('Dane godzinowe','Hourly data'),('Podział czasowy','Temporal split'),('Historia 168 h','168 h history'),('Trzy modele','Three models'),('Prognoza 24 h','24 h forecast')],layers=[('168 × 1','Log-count history'),('GRU · 32','Recurrent state'),('+ 24 × 6','Known calendar'),('Dense · 64','ReLU'),('Dense · 24','Hourly predictions')],model_note=('Pokazana architektura GRU została wytrenowana. W tym eksperymencie usługę domyślnie obsługuje lepszy na walidacji baseline sezonowy.','The illustrated GRU architecture was trained. In this experiment the service defaults to the seasonal baseline, which performed better on validation.'),example=('Wybieramy historyczny moment prognozy. System zwraca 24 wartości, pokazuje rzeczywiste obserwacje i umożliwia porównanie metod bez ponownego treningu.','Choose a historical forecast origin. The system returns 24 values, overlays observed demand and compares methods without retraining.'),limits=('Dane dotyczą jednego miasta w latach 2011–2012. To odtworzenie eksperymentu, nie prognoza dzisiejszego ruchu. GRU i boosting przegrały z baseline; nie ukrywamy tego wyniku. Przyszła pogoda nie jest wejściem.','Data covers one city in 2011–2012. This is an experiment replay, not a forecast of today’s traffic. GRU and boosting lost to the baseline; that result is retained. Future weather is not an input.'),source='UCI Bike Sharing · CC BY 4.0',source_url='https://archive.ics.uci.edu/dataset/275/bike+sharing+dataset',stack='React · TypeScript · FastAPI · PyTorch · scikit-learn'),
dict(slug='intentroute',folder='02-intentroute',name='IntentRoute',category=('Rozumienie zgłoszeń','Intent classification'),headline=('Każda wiadomość.','Every message.'),accent=('Właściwy kierunek.','The right direction.'),intro=('Zbudowaliśmy klasyfikator, który odczytuje treść zgłoszenia i wskazuje najbardziej prawdopodobną intencję spośród 77 kategorii bankowych. Z alternatywami i możliwością wstrzymania automatycznej decyzji.','We built a classifier that reads a support message and identifies its most likely intent among 77 banking categories. With alternatives and an option to abstain from an automatic decision.'),problem=('Najpierw zrozumieć, potem przekazać.','Understand first. Route second.'),problem_body=('Klienci opisują ten sam problem na różne sposoby. Ręczne sortowanie wiadomości zabiera czas, a sztywne słowa kluczowe gubią kontekst.','Customers describe the same issue in different ways. Manual sorting takes time, while rigid keyword rules miss context.'),features=[('77 intencji','77 intents','Jedna wiadomość trafia do przejrzystego zestawu kategorii.','A message maps to a clear set of support categories.'),('Top 3 i próg pewności','Top 3 and confidence threshold','Model pokazuje alternatywy; niska pewność sygnalizuje potrzebę sprawdzenia.','The model presents alternatives; low confidence signals a need for review.'),('Analiza partii CSV','CSV batch analysis','Do 100 wiadomości naraz, z zachowaniem lokalnego przetwarzania.','Up to 100 messages per batch, processed locally.')],uses=[('Wstępny routing','Initial routing','Podpowiedź kolejki lub zespołu dla przychodzących zgłoszeń.','Suggest a queue or team for incoming support requests.'),('Analityka tematów','Topic analytics','Rozkład intencji pomaga zrozumieć dominujące powody kontaktu.','Intent distribution helps reveal the main reasons for contacting support.'),('Wsparcie operatora','Agent assistance','Kategorie są sugestią, a nie nieodwołalną decyzją systemu.','Categories are suggestions, not irreversible system decisions.')],steps=[('Tekst zgłoszenia','Message text'),('Tokenizer · 128','Tokenizer · 128'),('MiniLM · 384','MiniLM · 384'),('Głowica MLP','MLP head'),('Top 3 / abstencja','Top 3 / abstention')],layers=[('≤128 tokens','Input message'),('MiniLM · 12 layers','Frozen multilingual encoder'),('384 dimensions','Sentence embedding'),('Dense · 192','Trained ReLU head'),('77 classes','Class probabilities')],model_note=('Encoder MiniLM jest gotowy i zamrożony. Trenowaliśmy głowicę MLP; porównaniem był TF-IDF z regresją logistyczną.','The pretrained MiniLM encoder is frozen. We trained the MLP head and compared it with TF-IDF plus logistic regression.'),example=('„Moja nowa karta jeszcze nie dotarła. Gdzie jest przesyłka?” → dostawa karty. Interfejs pokazuje także alternatywne intencje i wynik modelu.','“My new card has not arrived yet. Where is the delivery?” → card arrival. The interface also shows alternative intents and the model score.'),limits=('Główne wyniki dotyczą angielskiego BANKING77. Polska kontrola ma 12 autorskich przykładów: accuracy 66,67%. To diagnostyka, nie polski benchmark. Encoder analizuje pierwsze 128 tokenów; pewność nie jest gwarancją poprawności.','Main results concern English BANKING77. The Polish control has 12 author-written examples, with 66.67% accuracy. It is a diagnostic, not a Polish benchmark. The encoder reads the first 128 tokens; confidence does not guarantee correctness.'),source='BANKING77 · CC BY 4.0',source_url='https://huggingface.co/datasets/PolyAI/banking77',stack='React · FastAPI · Sentence Transformers · scikit-learn'),
dict(slug='terravision',folder='03-terravision',name='TerraVision',category=('Computer vision','Computer vision'),headline=('Od pikseli','From pixels'),accent=('do krajobrazu.','to landscapes.'),intro=('Zbudowaliśmy aplikację, która rozpoznaje dziesięć klas pokrycia terenu na wycinkach zdjęć satelitarnych. Do wyniku dodaje rozkład klas i Grad-CAM, aby można było zajrzeć do zachowania sieci.','We built an application that recognizes ten land-cover classes in satellite image tiles. It adds class scores and Grad-CAM so users can inspect the network’s behavior.'),problem=('Co naprawdę pokazuje ten obraz?','What does this image show?'),problem_body=('Duże zbiory zdjęć wymagają powtarzalnej klasyfikacji. Ważny jest nie tylko wynik, ale też sposób jego porównania z prostszym modelem i możliwość obejrzenia błędów.','Large image collections need repeatable classification. The result matters, but so do comparison with a simpler model and the ability to inspect mistakes.'),features=[('10 klas terenu','10 land-cover classes','Uprawy, lasy, zabudowa, woda i pozostałe klasy EuroSAT.','Crops, forests, built areas, water and the remaining EuroSAT classes.'),('ResNet18 po treningu','Fine-tuned ResNet18','Transfer learning z dostosowaną głowicą klasyfikacji.','Transfer learning with an adapted classification head.'),('Wgląd przez Grad-CAM','Inspection with Grad-CAM','Nakładka aktywacji ułatwia oglądanie reakcji sieci na konkretny wycinek.','An activation overlay helps inspect the network’s response to a tile.')],uses=[('Katalogowanie zdjęć','Image cataloging','Wstępne porządkowanie zbiorów obrazów satelitarnych.','Initial organization of satellite-image collections.'),('Prototyp analityki przestrzennej','Spatial analytics prototype','Punkt startowy do rozwiązania dopasowanego do regionu i źródła zdjęć.','A starting point for a solution tailored to a region and imagery source.'),('Kontrola modelu','Model inspection','Porównanie pomyłek między klasami i oglądanie obszarów aktywacji.','Compare class-level mistakes and inspect activation regions.')],steps=[('Wycinek RGB','RGB tile'),('64 × 64 / normalizacja','64 × 64 / normalization'),('ResNet18','ResNet18'),('10 klas','10 classes'),('Wynik + Grad-CAM','Prediction + Grad-CAM')],layers=[('3 × 64 × 64','Satellite RGB input'),('Conv · 64','7 × 7 learned kernels'),('Residual stages','64 → 128 → 256 → 512'),('Average pooling','512 features'),('Linear · 10','Land-cover classes')],model_note=('Zmodyfikowaliśmy warstwę końcową ResNet18 na 10 klas i dostroiliśmy sieć. Wizualizacja filtrów poniżej pochodzi z zapisanych wag, a nie z grafiki stockowej.','We replaced the ResNet18 output layer with a 10-class head and fine-tuned the network. The filter visualization below comes from saved weights, not stock imagery.'),example=('Wybór próbki „Uprawy roczne” → klasyfikacja wycinka, rozkład prawdopodobieństw i przełączana nakładka Grad-CAM. Można też przesłać własny plik JPG, PNG lub WEBP.','Select an annual-crop sample to classify the tile, inspect class scores and toggle Grad-CAM. Users can also upload a JPG, PNG or WEBP file.'),limits=('Test obejmuje 4050 obrazów EuroSAT. Rozdzieliliśmy identyczne hashe między zbiorami; nie potwierdziliśmy generalizacji na nowe regiony. Grad-CAM jest wizualizacją aktywacji, nie dowodem przyczynowym ani pomiarem geodezyjnym.','The test includes 4,050 EuroSAT images. Identical hashes do not cross splits; generalization to new regions has not been established. Grad-CAM visualizes activation, not causality or surveying measurements.'),source='EuroSAT RGB · MIT',source_url='https://zenodo.org/records/7711810',stack='React · FastAPI · PyTorch · torchvision · Pillow'),
dict(slug='machinesentinel',folder='04-machinesentinel',name='MachineSentinel',category=('Detekcja anomalii','Anomaly detection'),headline=('Nietypowe sygnały.','Unusual signals.'),accent=('Widoczne w danych.','Visible in the data.'),intro=('Zbudowaliśmy lokalny monitor eksperymentalny, który porównuje odczyty pięciu czujników z profilem normalnej pracy. Wynik anomalii ma jawny próg i jest pokazany razem z ograniczeniami modelu.','We built a local experimental monitor that compares five sensor readings with a normal-operation profile. Its anomaly score has an explicit threshold and is presented alongside model limitations.'),problem=('Odróżnić odchylenie od zwykłej zmienności.','Separate deviations from normal variation.'),problem_body=('Pojedynczy wysoki odczyt nie musi oznaczać awarii. Potrzebny jest wspólny obraz temperatury, obrotów, momentu i zużycia narzędzia.','A single high reading need not mean a failure. Temperature, rotational speed, torque and tool wear need to be considered together.'),features=[('Autoencoder normalnej pracy','Normal-operation autoencoder','Sieć uczy się rekonstrukcji normalnych obserwacji.','The network learns to reconstruct normal observations.'),('Porównanie z Isolation Forest','Isolation Forest comparison','Dwie metody, próg dobrany na walidacji i jawne metryki.','Two methods, a validation-selected threshold and explicit metrics.'),('Forma i CSV','Form and CSV','Analiza pojedynczego odczytu lub pliku, wraz z zakresami treningowymi.','Analyze one reading or a file, with training-range context.')],uses=[('Eksploracja telemetrii','Telemetry exploration','Wyszukiwanie nietypowych kombinacji sygnałów do dalszego przeglądu.','Find unusual signal combinations for further inspection.'),('Prototyp monitoringu','Monitoring prototype','Ocena, jakie dodatkowe dane są potrzebne przed wdrożeniem.','Assess which additional data is needed before deployment.'),('Analiza kompromisów','Trade-off analysis','Świadomy wybór między przeoczonymi zdarzeniami a fałszywymi alarmami.','Make an informed trade-off between missed events and false alarms.')],steps=[('5 sygnałów','5 signals'),('Skalowanie z train','Train-only scaling'),('Kompresja do 2D','2D bottleneck'),('Rekonstrukcja','Reconstruction'),('Błąd / próg','Error / threshold')],layers=[('5 features','Temperature · rpm · torque · wear'),('Dense · 12','Tanh encoder'),('Bottleneck · 2','Compressed representation'),('Dense · 12','Tanh decoder'),('Output · 5','Reconstruction error')],model_note=('Architektura 5 → 12 → 2 → 12 → 5. Trening wyłącznie na normalnych obserwacjach; etykiety awarii nie są wejściem modelu.','Architecture: 5 → 12 → 2 → 12 → 5. Training uses normal observations only; failure labels are not model inputs.'),example=('Testowy odczyt z prędkością 2737 rpm i momentem 8,8 Nm uzyskał wynik anomalii 1,776 przy progu 0,644. To wskazówka do przeglądu, nie diagnoza przyczyny.','A test reading with 2,737 rpm and 8.8 Nm torque produced an anomaly score of 1.776 against a 0.644 threshold. It is an inspection signal, not a diagnosis of cause.'),limits=('AI4I jest zbiorem syntetycznym. Przy wybranym progu recall wynosi 29,41%, precision 24,59%: wiele awarii pozostaje niewykrytych. Wynik nie jest prawdopodobieństwem awarii; projekt nie zastępuje przemysłowego systemu bezpieczeństwa.','AI4I is synthetic. At the selected threshold, recall is 29.41% and precision is 24.59%: many failures remain undetected. The score is not a failure probability; this project does not replace an industrial safety system.'),source='AI4I 2020 · CC BY 4.0',source_url='https://archive.ics.uci.edu/dataset/601/ai4i+2020+predictive+maintenance+dataset',stack='React · FastAPI · PyTorch · scikit-learn'),
dict(slug='basketwise',folder='05-basketwise',name='BasketWise',category=('System rekomendacji','Recommendation system'),headline=('Kolejny produkt.','The next product.'),accent=('Lepsze dopasowanie.','A better fit.'),intro=('Zbudowaliśmy silnik rekomendacji, który łączy historię zakupów z rankingiem produktów. Porównuje popularność, podobieństwo koszyków i faktoryzację macierzy na przyszłych zakupach.','We built a recommendation engine that connects purchase history with a product ranking. It compares popularity, basket similarity and matrix factorization against future purchases.'),problem=('Co zaproponować po pierwszym wyborze?','What should follow the first choice?'),problem_body=('Lista bestsellerów jest dobrym początkiem, ale nie uwzględnia zainteresowań konkretnej osoby. Chcieliśmy sprawdzić, ile daje wykorzystanie historii.','Bestsellers provide a useful starting point, but ignore individual interests. We wanted to measure what purchase history adds.'),features=[('Rekomendacje z historii','History-based recommendations','Wybrane już produkty są wykluczane z kolejnej listy.','Already selected products are excluded from recommendations.'),('Obsługa nowego użytkownika','Cold-start handling','Gdy brakuje historii, system wraca do popularności z train.','When history is absent, the system falls back to training popularity.'),('Ranking na pełnym katalogu','Full-catalog ranking','1600 kandydatów; bez sztucznego ułatwiania testu przez losowanie negatywów.','1,600 candidates; no artificially easy sampled-negative evaluation.')],uses=[('Odkrywanie katalogu','Catalog discovery','Pomoc w znalezieniu kolejnych produktów powiązanych z zainteresowaniem użytkownika.','Help users discover products connected to their interests.'),('Warstwa personalizacji','Personalization layer','Prototyp do integracji z katalogiem i rzeczywistą historią sklepu.','A prototype for integration with a store’s catalog and actual history.'),('Porównanie strategii','Strategy comparison','Oddzielenie jakości rankingu offline od biznesowego testu konwersji.','Separate offline ranking quality from a business conversion test.')],steps=[('Transakcje','Transactions'),('Podział po czasie','Temporal split'),('Macierz użytkownik × produkt','User × item matrix'),('48 czynników','48 latent factors'),('Top 10 bez historii','Top 10 excluding seen items')],layers=[('Users × 1600 items','Binary train interactions'),('SVD · rank 48','Learned latent factors'),('History vector','Sum selected item factors'),('Full-catalog scores','1600 candidates'),('Filter + rank','Exclude previously seen items')],model_note=('Faktoryzacja nie jest siecią neuronową. Macierz interakcji jest rozkładana na 48 wymiarów, z których powstaje ranking kandydatów.','Factorization is not a neural network. The interaction matrix is decomposed into 48 dimensions used to score candidate products.'),example=('Biały świecznik w kształcie serca → w rekomendacjach pojawiają się powiązane produkty, np. czerwony wariant i podobne dekoracje. Powód wyboru odwołuje się do historii.','A white heart-shaped candle holder leads to related recommendations, such as a red variant and similar decorations. The explanation refers to purchase history.'),limits=('Wynik dotyczy produktów obecnych w treningowym katalogu i nowych dla użytkownika. NDCG nie jest konwersją ani przychodem. Dane są historyczne, ceny w GBP; interfejs demonstracyjny nie jest sklepem.','Evaluation covers training-catalog products that are new to the user. NDCG is not conversion or revenue. Data and GBP prices are historical; the demo interface is not a shop.'),source='UCI Online Retail · CC BY 4.0',source_url='https://archive.ics.uci.edu/dataset/352',stack='React · FastAPI · SciPy sparse · scikit-learn'),
dict(slug='reviewpulse',folder='06-reviewpulse',name='ReviewPulse',category=('Analiza opinii','Sentiment analysis'),headline=('Opinie klientów.','Customer feedback.'),accent=('Czytelny sygnał.','A clearer signal.'),intro=('Zbudowaliśmy analizator opinii, który rozpoznaje pozytywny i negatywny wydźwięk tekstu. Działa lokalnie, obsługuje pojedyncze komentarze i partie CSV, pokazuje także niepewność.','We built a feedback analyzer that distinguishes positive and negative sentiment. It runs locally, handles individual comments and CSV batches, and exposes uncertainty.'),problem=('Nie zgubić sygnału w setkach komentarzy.','Find the signal across hundreds of comments.'),problem_body=('Ocena liczbowa nie wyjaśnia doświadczenia. Tekst zawiera dodatkowy kontekst, ale jego ręczny przegląd jest czasochłonny.','A numerical rating does not explain an experience. Text adds context, but reviewing it manually takes time.'),features=[('Dwie jawne klasy','Two explicit classes','Pozytywna lub negatywna opinia; bez udawanej klasy neutralnej.','Positive or negative feedback, without a pretend neutral class.'),('Lokalna analiza','Local analysis','Treść nie musi opuszczać urządzenia ani trafiać do zewnętrznego API.','Text need not leave the device or reach an external API.'),('Porównanie domen','Domain comparison','Wyniki dla różnych źródeł i polskiej kontroli są pokazane osobno.','Results for different sources and Polish controls are reported separately.')],uses=[('Przegląd feedbacku','Feedback triage','Wstępne porządkowanie opinii przed przeglądem zespołu.','Initial organization of feedback before team review.'),('Monitoring doświadczeń','Experience monitoring','Prototyp podsumowania tonu komentarzy w konkretnym kanale.','Prototype sentiment summaries for a particular feedback channel.'),('Analiza jakości danych','Data-quality analysis','Wykrywanie przypadków niepewnych i obszarów wymagających nowej anotacji.','Identify uncertain cases and areas needing additional annotation.')],steps=[('Opinia lub CSV','Review or CSV'),('Tokenizer · 128','Tokenizer · 128'),('MiniLM · 384','MiniLM · 384'),('MLP · 64','MLP · 64'),('Ton + niepewność','Sentiment + uncertainty')],layers=[('≤128 tokens','Review text'),('MiniLM · 12 layers','Frozen multilingual encoder'),('384 dimensions','Sentence embedding'),('Dense · 64','Learned ReLU head'),('Binary output','Positive / negative')],model_note=('Wyuczony klasyfikator korzysta z gotowych wielojęzycznych embeddings. Porównujemy go z niezależnym baseline TF-IDF, a nie z samym wynikiem treningu.','The trained classifier uses pretrained multilingual embeddings. We compare it with a separate TF-IDF baseline, not merely its training score.'),example=('„Obsługa była bardzo miła, a jedzenie doskonałe.” → pozytywny wydźwięk. Wynik modelu i alternatywa są widoczne obok tekstu.','“The service was very friendly and the food was excellent.” → positive sentiment. The model score and alternative class are shown alongside the text.'),limits=('Dane źródłowe zawierają wyraźnie pozytywne i negatywne zdania, bez neutralnych. Sarkazm, mieszane opinie i nowe domeny mogą pogarszać wynik. Polska kontrola obejmuje 16 autorskich przykładów.','The source contains clearly positive and negative sentences, with no neutral class. Sarcasm, mixed opinions and new domains may reduce quality. The Polish control has 16 author-written examples.'),source='UCI Sentiment Labelled Sentences · CC BY 4.0',source_url='https://archive.ics.uci.edu/dataset/331/sentiment+labelled+sentences',stack='React · FastAPI · Sentence Transformers · scikit-learn'),
dict(slug='ai-desk',folder='07-ai-desk',name='AI Desk',category=('Asystent wiedzy / RAG','Knowledge assistant / RAG'),headline=('Zadaj pytanie.','Ask a question.'),accent=('Zobacz źródło.','See the source.'),intro=('Zbudowaliśmy lokalnego asystenta dokumentów z kontami, rolami i historią rozmów. Odpowiedź łączy z konkretnymi fragmentami, a wyszukiwanie najpierw respektuje uprawnienia użytkownika.','We built a local document assistant with accounts, roles and conversation history. Answers link to specific passages, and retrieval respects user permissions before searching.'),problem=('Wiedza jest w dokumentach. Odpowiedź jest potrzebna teraz.','The knowledge is in documents. The answer is needed now.'),problem_body=('Procedury, produkty i zasady są rozproszone. Asystent powinien pomagać znaleźć odpowiedź, nie rozszerzać dostępu ani ukrywać pochodzenia informacji.','Procedures, products and policies are scattered. An assistant should help locate an answer without expanding access or hiding where information came from.'),features=[('Źródła obok odpowiedzi','Sources beside the answer','Kliknięcie cytowania otwiera konkretny fragment dokumentu.','Clicking a citation opens a specific document passage.'),('Role przed wyszukiwaniem','Permissions before retrieval','SQL filtruje dostępne dokumenty zanim powstanie ranking.','SQL filters accessible documents before ranking takes place.'),('Lokalny model i historia','Local model and history','Qwen przez Ollama, zapisane rozmowy, dokumenty TXT/MD/PDF.','Qwen via Ollama, saved conversations, TXT/MD/PDF documents.')],uses=[('Wewnętrzna baza wiedzy','Internal knowledge base','Szukanie procedur i zasad w materiałach dostępnych dla roli pracownika.','Find procedures and policies in material accessible to an employee’s role.'),('Wsparcie wdrożenia pracownika','Onboarding support','Szybki dostęp do odpowiednich dokumentów i ich fragmentów.','Quick access to relevant documents and passages.'),('Asystent dokumentacji produktu','Product-documentation assistant','Odpowiedzi o funkcjach oparte na przygotowanej bazie materiałów.','Feature answers grounded in a prepared documentation collection.')],steps=[('Sesja / użytkownik','Session / user'),('ACL w SQL','SQL permission filter'),('Embedding + ranking','Embedding + ranking'),('Qwen lokalnie','Local Qwen'),('Cytaty + historia','Citations + history')],layers=[('20 topics / PL+EN','40 fictional documents'),('SQL ACL','Only authorized chunks'),('MiniLM · 384','Cosine + title overlap'),('Qwen3.5 · 4B','Pretrained local generator'),('Citation-ID validation','Buffered SSE + SQLite history')],model_note=('Nie trenowaliśmy LLM od zera. To system RAG z gotowym encoderem i generatorem. Diagram pokazuje architekturę aplikacji; projekcja poniżej pochodzi z rzeczywistych embeddings demonstracyjnych dokumentów.','We did not train an LLM from scratch. This is a RAG system with pretrained encoder and generator. The diagram shows the application architecture; the projection below uses actual demo-document embeddings.'),example=('„Jaki jest roczny budżet szkoleniowy pracownika?” → „2000 PLN” z cytowaniem właściwego dokumentu. Baza jest fikcyjna; odpowiedź opisuje politykę demonstracyjnej firmy.','“What is the employee’s annual learning budget?” → “2000 PLN” with a citation to the relevant document. The corpus is fictional; this describes a demo-company policy.'),limits=('70/70 poprawnie zakończonych strumieni, 67/70 kontroli retrieval. Trzy ogólne polskie pytania otrzymały odmowę. W czterech testach złośliwych dokumentów pojawiły się nieprecyzyjne cytowania. Historia jest zapisana, lecz wcześniejsze wypowiedzi nie są kontekstem LLM. Identyfikator cytatu nie gwarantuje poprawności każdego twierdzenia.','70/70 completed streams, 67/70 retrieval checks. Three generic Polish questions received abstentions. Four adversarial-document tests showed imprecise citations. History is saved, but earlier messages are not sent as LLM context. A valid citation ID does not guarantee every claim is supported.'),source='Fikcyjny korpus Antillia North · MIT / pretrained models · Apache-2.0',source_url='https://github.com/Flyingzaptop/antillia-ml-portfolio/tree/main/07-ai-desk',stack='React · Django REST · SQLite · MiniLM · Ollama / Qwen3.5')
]
